INSERT INTO content_items (id, topic_id, source_id, url, raw_text, clean_text, content_hash, language, captured_at, credibility_score_at_capture, narrative_cluster_id, labels, created_at, updated_at, org_id) VALUES
('kl-ci-01','kl-cyd-001','kl-src-01','https://thehindu.com/news/national/kerala/cyber-dome-predator-ring','Cyber Dome busts online predator ring','Kerala Police Cyber Dome busts interstate online predator ring targeting school children through gaming platforms. 6 suspects arrested across Kerala, Tamil Nadu, and Karnataka. Investigation revealed suspects created fake gaming profiles to befriend minors on Roblox and Free Fire, then migrated conversations to Telegram and Instagram DMs for exploitation. Over 200 potential victims identified. POCSO cases registered in Ernakulam and Thiruvananthapuram.', md5('kl-ci-01'),'en',NOW()-INTERVAL '28 days',85.0,'kl-cl-01','{"classification":"SECRET","domain":"child_protection","owner_org":"cyber","author_handle":"The Hindu","author_id":"kl-src-01","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.7,"label":"negative"},"keywords":["predator ring","gaming","Roblox","Telegram","POCSO","Cyber Dome"]}'::jsonb,NOW()-INTERVAL '28 days',NOW(),'org_cyber'),
('kl-ci-02','kl-cyd-001','kl-src-06','https://t.me/cybercrime_alert_kl/101','Instagram grooming pattern alert','ALERT: Emerging pattern — fake Instagram profiles targeting school-age children in Kochi and Thrissur. Profile characteristics: recently created, stock photos, follows only minors, sends DMs within hours. At least 15 reports to Cyber Dome in last week. Report suspicious profiles to cyberdome@keralapolice.gov.in. Phone: +91-471-2721547.', md5('kl-ci-02'),'en',NOW()-INTERVAL '27 days',22.0,'kl-cl-01','{"classification":"SECRET","domain":"child_protection","owner_org":"cyber","author_handle":"@cybercrime_alert_kl","author_id":"cybercrime_alert_kl","engagement":{"likes":34,"comments":56,"shares":0,"views":890,"forwards":22},"sentiment":{"compound":-0.8,"label":"negative"},"keywords":["Instagram","grooming","Kochi","Thrissur","fake profiles","minors"]}'::jsonb,NOW()-INTERVAL '27 days',NOW(),'org_cyber'),
('kl-ci-03','kl-cyd-001','kl-src-07','https://t.me/online_safety_watch_in/205','Gaming platform migration pattern','WARNING: Documented predator migration pattern — initial contact on public gaming platforms (BGMI, Free Fire), followed by friend request on Instagram, then shift to Telegram or WhatsApp for private communication. Parents: check children phone for unknown Telegram contacts. Handle spotted: @safe_gamer_mentor (fake safety account).', md5('kl-ci-03'),'en',NOW()-INTERVAL '26 days',18.0,'kl-cl-01','{"classification":"SECRET","domain":"child_protection","owner_org":"cyber","author_handle":"@online_safety_watch_in","author_id":"online_safety_watch_in","engagement":{"likes":45,"comments":30,"shares":0,"views":1200,"forwards":35},"sentiment":{"compound":-0.75,"label":"negative"},"keywords":["gaming","migration","BGMI","Free Fire","predator","pattern"]}'::jsonb,NOW()-INTERVAL '26 days',NOW(),'org_cyber'),
('kl-ci-04','kl-cyd-001','kl-src-02','https://manoramaonline.com/news/kerala/kochi-school-sextortion','Sextortion ring targeting Kochi school students','Manorama Online: Kochi City Police arrest 3 persons running sextortion racket targeting school students. Suspects used fake female profiles on Instagram to solicit personal images, then blackmailed victims for money via UPI. 12 victims identified in Ernakulam district. One suspect operated from West Bengal. Phone: +91-94960-11111 used across multiple cases.', md5('kl-ci-04'),'en',NOW()-INTERVAL '24 days',80.0,'kl-cl-01','{"classification":"SECRET","domain":"child_protection","owner_org":"cyber","author_handle":"Manorama Online","author_id":"kl-src-02","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.85,"label":"negative"},"keywords":["sextortion","Kochi","school","Instagram","UPI","blackmail"]}'::jsonb,NOW()-INTERVAL '24 days',NOW(),'org_cyber'),
('kl-ci-05','kl-cyd-001','kl-src-09','https://cyberdome.kerala.gov.in/advisory-online-grooming','Cyber Dome advisory on online grooming','Kerala Police Cyber Dome issues advisory on online grooming: 340% increase in cybertipline reports related to child exploitation in Q1 2026 vs Q1 2025. Top platforms: Instagram (42%), Telegram (28%), WhatsApp (18%), gaming apps (12%). Parents advised to monitor children online activity. Schools to conduct cyber safety workshops.', md5('kl-ci-05'),'en',NOW()-INTERVAL '22 days',92.0,'kl-cl-01','{"classification":"SECRET","domain":"child_protection","owner_org":"cyber","author_handle":"Kerala Cyber Dome","author_id":"kl-src-09","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.5,"label":"negative"},"keywords":["advisory","grooming","cybertipline","340% increase","Instagram","Telegram"]}'::jsonb,NOW()-INTERVAL '22 days',NOW(),'org_cyber'),
('kl-ci-06','kl-cyd-001','kl-src-08','https://t.me/pocso_tracker_kl/78','Discord server predator activity','POCSO Tracker: Discord server identified where suspects share tips on contacting minors. Server has 500+ members, Indian operators. Infiltration by Cyber Dome undercover team ongoing. Server admin uses handle @darkmod_admin. Crypto wallet address bc1q_fake_wallet_1 found in payment channel.', md5('kl-ci-06'),'en',NOW()-INTERVAL '20 days',20.0,'kl-cl-01','{"classification":"SECRET","domain":"child_protection","owner_org":"cyber","author_handle":"@pocso_tracker_kl","author_id":"pocso_tracker_kl","engagement":{"likes":12,"comments":25,"shares":0,"views":560,"forwards":18},"sentiment":{"compound":-0.9,"label":"negative"},"keywords":["Discord","predator","infiltration","Cyber Dome","crypto wallet"]}'::jsonb,NOW()-INTERVAL '20 days',NOW(),'org_cyber'),
('kl-ci-07','kl-cyd-001','kl-src-03','https://mathrubhumi.com/news/kerala/tvm-cyber-arrest','Thiruvananthapuram cyber arrest — teacher grooming students','Mathrubhumi: Thiruvananthapuram police arrest private tuition teacher for grooming 4 students via WhatsApp. Suspect used separate phone number (+91-94960-22222) for contacting victims. School reported after student confided in counselor. POCSO Section 11 + IT Act Section 67B charges filed.', md5('kl-ci-07'),'en',NOW()-INTERVAL '18 days',78.0,'kl-cl-01','{"classification":"SECRET","domain":"child_protection","owner_org":"cyber","author_handle":"Mathrubhumi","author_id":"kl-src-03","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.8,"label":"negative"},"keywords":["Thiruvananthapuram","teacher","grooming","WhatsApp","POCSO","IT Act"]}'::jsonb,NOW()-INTERVAL '18 days',NOW(),'org_cyber'),
('kl-ci-08','kl-cyd-001','kl-src-12','https://reddit.com/r/Kerala/comments/fake123','Reddit thread: Parents concerned about online safety','Reddit r/Kerala thread with 200+ comments. Parents sharing experiences of children receiving suspicious friend requests on Instagram. Multiple mentions of same profile pattern — bio includes "gaming mentor" or "free coaching". Users reporting to Cyber Dome via email. Community awareness growing.', md5('kl-ci-08'),'en',NOW()-INTERVAL '16 days',30.0,'kl-cl-01','{"classification":"OPEN","domain":"child_protection","owner_org":"cyber","author_handle":"r/Kerala","author_id":"kl-src-12","engagement":{"likes":234,"comments":208,"shares":0,"views":15000},"sentiment":{"compound":-0.4,"label":"negative"},"keywords":["parents","Instagram","friend requests","gaming mentor","community","reporting"]}'::jsonb,NOW()-INTERVAL '16 days',NOW(),'org_cyber'),
('kl-ci-09','kl-cyd-001','kl-src-04','https://ndtv.com/kerala-news/cyber-dome-operation-shield','Operation Shield: Cyber Dome multi-state crackdown','NDTV: Kerala Cyber Dome launches Operation Shield — coordinated multi-state crackdown on online predator networks. 14 arrests across 5 states. Digital forensics on 23 seized devices ongoing. International coordination with Interpol ICSE database. SP Cyber Crime: This is the largest such operation in Kerala history.', md5('kl-ci-09'),'en',NOW()-INTERVAL '14 days',82.0,'kl-cl-01','{"classification":"SECRET","domain":"child_protection","owner_org":"cyber","author_handle":"NDTV","author_id":"kl-src-04","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.3,"label":"negative"},"keywords":["Operation Shield","Cyber Dome","multi-state","Interpol","ICSE","arrests"]}'::jsonb,NOW()-INTERVAL '14 days',NOW(),'org_cyber'),
('kl-ci-10','kl-cyd-001','kl-src-06','https://t.me/cybercrime_alert_kl/115','WhatsApp group distributing exploitation material','CRITICAL: WhatsApp group identified distributing child exploitation material. Group admin phone: +91-94960-11111 (same number linked to Kochi sextortion case). 340 members. Reported to WhatsApp Trust & Safety and NCMEC. Cyber Dome case registered. DO NOT join or share — possession is criminal offense under IT Act 67B.', md5('kl-ci-10'),'en',NOW()-INTERVAL '12 days',22.0,'kl-cl-01','{"classification":"SECRET","domain":"child_protection","owner_org":"cyber","author_handle":"@cybercrime_alert_kl","author_id":"cybercrime_alert_kl","engagement":{"likes":8,"comments":15,"shares":0,"views":340,"forwards":10},"sentiment":{"compound":-0.95,"label":"negative"},"keywords":["WhatsApp","exploitation material","NCMEC","IT Act 67B","phone number"]}'::jsonb,NOW()-INTERVAL '12 days',NOW(),'org_cyber'),
('kl-ci-11','kl-cyd-001','kl-src-13','https://youtube.com/watch?v=cyberdome_awareness','Cyber Dome awareness campaign video','Kerala Police Cyber Dome releases awareness video: How predators target children online. 500K views in 2 days. Covers gaming platform grooming, fake profile identification, reporting mechanisms. Malayalam and English versions. Schools asked to screen during cyber safety week.', md5('kl-ci-11'),'en',NOW()-INTERVAL '10 days',88.0,'kl-cl-01','{"classification":"OPEN","domain":"child_protection","owner_org":"cyber","author_handle":"Kerala Police Official","author_id":"kl-src-13","engagement":{"likes":3400,"comments":450,"shares":890,"views":500000},"sentiment":{"compound":0.3,"label":"positive"},"keywords":["awareness","video","grooming","reporting","schools","Malayalam"]}'::jsonb,NOW()-INTERVAL '10 days',NOW(),'org_cyber'),
('kl-ci-12','kl-cyd-001','kl-src-05','https://indianexpress.com/kerala-cyber-dome-ai-detection','Cyber Dome deploys AI for predator detection','Indian Express: Kerala Cyber Dome becomes first state police unit to deploy AI-driven social media monitoring for predator pattern detection. System flags suspicious account behavior patterns — rapid following of minor accounts, specific language patterns in DMs. 45 accounts flagged in first week of deployment.', md5('kl-ci-12'),'en',NOW()-INTERVAL '8 days',80.0,'kl-cl-01','{"classification":"SECRET","domain":"child_protection","owner_org":"cyber","author_handle":"Indian Express","author_id":"kl-src-05","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":0.2,"label":"positive"},"keywords":["AI","detection","social media","monitoring","pattern","accounts flagged"]}'::jsonb,NOW()-INTERVAL '8 days',NOW(),'org_cyber'),

-- ── Cluster 2: AI-Generated Synthetic Content & Deepfake Detection (10 items) ──
('kl-ci-13','kl-cyd-001','kl-src-11','https://missingkids.org/cybertipline-report-q1-2026','NCMEC CyberTipline Q1 2026: AI-generated content surge','NCMEC CyberTipline Q1 2026 report: 35% increase in reports flagged as AI-generated or synthetic exploitation content globally. India ranks 3rd in tip volume. Key indicators: metadata signatures of Stable Diffusion, abnormal skin texture patterns, inconsistent lighting. Automated hash matching insufficient — need visual AI detection.', md5('kl-ci-13'),'en',NOW()-INTERVAL '26 days',95.0,'kl-cl-02','{"classification":"SECRET","domain":"child_protection","owner_org":"cyber","author_handle":"NCMEC CyberTipline","author_id":"kl-src-11","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.6,"label":"negative"},"keywords":["NCMEC","AI-generated","synthetic","Stable Diffusion","hash matching","detection"]}'::jsonb,NOW()-INTERVAL '26 days',NOW(),'org_cyber'),
('kl-ci-14','kl-cyd-001','kl-src-09','https://cyberdome.kerala.gov.in/deepfake-detection-lab','Cyber Dome establishes deepfake detection lab','Kerala Cyber Dome establishes dedicated deepfake detection laboratory. Using DIRE (Diffusion Reconstruction Error) model for AI-generated image detection. Accuracy: 94% on known synthetic datasets. Processing 200+ images daily from tipline reports. Trained 15 officers in digital forensics evidence handling.', md5('kl-ci-14'),'en',NOW()-INTERVAL '24 days',92.0,'kl-cl-02','{"classification":"SECRET","domain":"child_protection","owner_org":"cyber","author_handle":"Kerala Cyber Dome","author_id":"kl-src-09","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":0.2,"label":"positive"},"keywords":["deepfake","DIRE","detection","laboratory","forensics","synthetic"]}'::jsonb,NOW()-INTERVAL '24 days',NOW(),'org_cyber'),
('kl-ci-15','kl-cyd-001','kl-src-07','https://t.me/online_safety_watch_in/220','Telegram channels sharing AI-generated content','WARNING: Telegram channels identified distributing AI-generated synthetic exploitation content. Channels using invite-only access. Content generated using fine-tuned open-source models. Metadata analysis shows EXIF stripped but PNG chunk data reveals generation parameters. Report channels: @safe_child_report.', md5('kl-ci-15'),'en',NOW()-INTERVAL '22 days',18.0,'kl-cl-02','{"classification":"SECRET","domain":"child_protection","owner_org":"cyber","author_handle":"@online_safety_watch_in","author_id":"online_safety_watch_in","engagement":{"likes":15,"comments":20,"shares":0,"views":670,"forwards":25},"sentiment":{"compound":-0.85,"label":"negative"},"keywords":["Telegram","AI-generated","synthetic","metadata","EXIF","open-source models"]}'::jsonb,NOW()-INTERVAL '22 days',NOW(),'org_cyber'),
('kl-ci-16','kl-cyd-001','kl-src-01','https://thehindu.com/news/national/kerala/deepfake-sextortion-case','Deepfake used in sextortion case against minor','The Hindu: First case in Kerala where AI-generated deepfake images used to sextort a 16-year-old student. Suspect created fake images using victim school photos scraped from social media. Demanded Rs 50,000 via UPI. Cyber Dome traced IP and arrested suspect in Kozhikode. UPI ID: predator_fake@paytm linked to multiple cases.', md5('kl-ci-16'),'en',NOW()-INTERVAL '20 days',85.0,'kl-cl-02','{"classification":"SECRET","domain":"child_protection","owner_org":"cyber","author_handle":"The Hindu","author_id":"kl-src-01","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.9,"label":"negative"},"keywords":["deepfake","sextortion","Kozhikode","UPI","school photos","AI-generated"]}'::jsonb,NOW()-INTERVAL '20 days',NOW(),'org_cyber'),
('kl-ci-17','kl-cyd-001','kl-src-14','http://ahmia.onion/synthetic-content-market','Dark web synthetic content marketplace detected','Dark web marketplace offering AI-generated synthetic exploitation content as a service. Prices in Monero (XMR). Operator claims content is legal because no real children involved — incorrect under Indian law (IT Act 67B covers virtual depictions). Server likely hosted in jurisdiction with weak enforcement. Wallet: 4_fake_xmr_wallet_addr.', md5('kl-ci-17'),'en',NOW()-INTERVAL '18 days',5.0,'kl-cl-02','{"classification":"SECRET","domain":"child_protection","owner_org":"cyber","author_handle":"Dark Web Monitor","author_id":"kl-src-14","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.9,"label":"negative"},"keywords":["dark web","marketplace","Monero","AI-generated","IT Act 67B","synthetic"]}'::jsonb,NOW()-INTERVAL '18 days',NOW(),'org_cyber'),
('kl-ci-18','kl-cyd-001','kl-src-04','https://ndtv.com/kerala-news/ai-deepfake-arrests','3 arrested for distributing deepfake exploitation material','NDTV: Kerala Police arrest 3 for distributing AI-generated deepfake exploitation material via Telegram. Suspects used Stable Diffusion XL locally. DIRE model analysis confirmed 97% synthetic probability. Seized computers contain 15,000+ generated images. IT Act 67B and POCSO charges filed. Phone: +91-94960-33333.', md5('kl-ci-18'),'en',NOW()-INTERVAL '16 days',82.0,'kl-cl-02','{"classification":"SECRET","domain":"child_protection","owner_org":"cyber","author_handle":"NDTV","author_id":"kl-src-04","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.7,"label":"negative"},"keywords":["deepfake","arrests","Stable Diffusion","DIRE","IT Act 67B","POCSO"]}'::jsonb,NOW()-INTERVAL '16 days',NOW(),'org_cyber'),
('kl-ci-19','kl-cyd-001','kl-src-08','https://t.me/pocso_tracker_kl/85','pHash matching identifies redistributed content','Technical update: Perceptual hash (pHash) matching identifies same exploitation content redistributed across 8 different Telegram channels after image modifications (cropping, filters, resolution changes). pHash catches near-duplicates that cryptographic hashes miss. Anveshak vision module processing 500 images/day for hash matching.', md5('kl-ci-19'),'en',NOW()-INTERVAL '14 days',20.0,'kl-cl-02','{"classification":"SECRET","domain":"child_protection","owner_org":"cyber","author_handle":"@pocso_tracker_kl","author_id":"pocso_tracker_kl","engagement":{"likes":10,"comments":18,"shares":0,"views":430,"forwards":12},"sentiment":{"compound":-0.4,"label":"negative"},"keywords":["pHash","matching","near-duplicate","Telegram","vision module","modifications"]}'::jsonb,NOW()-INTERVAL '14 days',NOW(),'org_cyber'),
('kl-ci-20','kl-cyd-001','kl-src-03','https://mathrubhumi.com/news/kerala/fake-video-school','AI-generated fake video targeting school student','Mathrubhumi: AI-generated fake video of 14-year-old Kozhikode student circulated on WhatsApp groups. Face-swap technology used with video from adult content site. Parents filed complaint. Cyber Dome DIRE analysis confirms synthetic generation. WhatsApp cooperating with takedown. Counseling provided to victim through District Child Protection Unit.', md5('kl-ci-20'),'en',NOW()-INTERVAL '11 days',78.0,'kl-cl-02','{"classification":"SECRET","domain":"child_protection","owner_org":"cyber","author_handle":"Mathrubhumi","author_id":"kl-src-03","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.85,"label":"negative"},"keywords":["fake video","face-swap","Kozhikode","WhatsApp","DIRE","counseling"]}'::jsonb,NOW()-INTERVAL '11 days',NOW(),'org_cyber'),
('kl-ci-21','kl-cyd-001','kl-src-10','https://ncpcr.gov.in/advisory-ai-generated-content','NCPCR advisory on AI-generated exploitation content','NCPCR issues national advisory: AI-generated virtual depictions of child exploitation are criminal under IT Act Section 67B and POCSO Act. No real child needed for offense. States directed to build detection capabilities. Kerala Cyber Dome cited as model for other states to follow.', md5('kl-ci-21'),'en',NOW()-INTERVAL '8 days',90.0,'kl-cl-02','{"classification":"SECRET","domain":"child_protection","owner_org":"cyber","author_handle":"NCPCR","author_id":"kl-src-10","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.3,"label":"negative"},"keywords":["NCPCR","advisory","AI-generated","IT Act 67B","POCSO","virtual depictions"]}'::jsonb,NOW()-INTERVAL '8 days',NOW(),'org_cyber'),
('kl-ci-22','kl-cyd-001','kl-src-06','https://t.me/cybercrime_alert_kl/120','EXIF metadata stripping detection','Technical advisory: Suspects now strip EXIF metadata from AI-generated content before distribution. However, PNG chunk analysis, JPEG quantization table patterns, and GAN artifact signatures still reveal synthetic origin. Cyber Dome forensics lab trained on these secondary detection methods. CLIP embedding clustering groups similar generated content.', md5('kl-ci-22'),'en',NOW()-INTERVAL '5 days',22.0,'kl-cl-02','{"classification":"SECRET","domain":"child_protection","owner_org":"cyber","author_handle":"@cybercrime_alert_kl","author_id":"cybercrime_alert_kl","engagement":{"likes":18,"comments":12,"shares":0,"views":540,"forwards":15},"sentiment":{"compound":-0.3,"label":"negative"},"keywords":["EXIF","metadata","PNG","GAN artifacts","CLIP","forensics"]}'::jsonb,NOW()-INTERVAL '5 days',NOW(),'org_cyber'),

